-- ==================================================================================
-- BANCO DE DADOS POPULADO
-- Projeto Monitoramento e Controle de Motores e Esteiras Transportadoras - Packbag
-- ==================================================================================

DROP DATABASE IF EXISTS bancoPI;
CREATE DATABASE bancoPI;
USE bancoPI;

-- Criação das Tabelas
CREATE TABLE empresa (
    idempresa INT AUTO_INCREMENT PRIMARY KEY,
    nome VARCHAR(100) NOT NULL,
    cnpj VARCHAR(18) NOT NULL,
    endereco VARCHAR(255),
    website VARCHAR(150),
    email VARCHAR(100)
);

CREATE TABLE setor (
    idsetor INT AUTO_INCREMENT PRIMARY KEY,
    nome VARCHAR(100),
    descricao TEXT,
    empresa_idempresa INT,
    FOREIGN KEY (empresa_idempresa) REFERENCES empresa(idempresa)
);

CREATE TABLE esteira (
    idesteira INT AUTO_INCREMENT PRIMARY KEY,
    nome VARCHAR(50),
    status VARCHAR(20),
    setor_idsetor INT,
    FOREIGN KEY (setor_idsetor) REFERENCES setor(idsetor)
);

CREATE TABLE sensor (
    idsensor INT AUTO_INCREMENT PRIMARY KEY,
    tipo VARCHAR(50),
    status VARCHAR(20),
    unidade VARCHAR(10),
    esteira_idesteira INT,
    FOREIGN KEY (esteira_idesteira) REFERENCES esteira(idesteira)
);

CREATE TABLE leitura (
    idleitura INT AUTO_INCREMENT PRIMARY KEY,
    data DATETIME,
    valor DECIMAL(10,2),
    alerta BOOLEAN,
    descricaoAlerta VARCHAR(255),
    sensor_idsensor INT,
    FOREIGN KEY (sensor_idsensor) REFERENCES sensor(idsensor)
);

CREATE TABLE motor (
    idmotor INT AUTO_INCREMENT PRIMARY KEY,
    modelo VARCHAR(50),
    status VARCHAR(20),
    direcao VARCHAR(20),
    esteira_idesteira INT,
    FOREIGN KEY (esteira_idesteira) REFERENCES esteira(idesteira)
);

CREATE TABLE usuario (
    idusuario INT AUTO_INCREMENT PRIMARY KEY,
    nome VARCHAR(100),
    login VARCHAR(100),
    senha VARCHAR(100),
    perfil VARCHAR(50)
);

CREATE TABLE comando (
    idcomando INT AUTO_INCREMENT PRIMARY KEY,
    data DATETIME,
    origem VARCHAR(50),
    motor_idmotor INT,
    usuario_idusuario INT,
    FOREIGN KEY (motor_idmotor) REFERENCES motor(idmotor),
    FOREIGN KEY (usuario_idusuario) REFERENCES usuario(idusuario)
);

